"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1814],{91814:a=>{a.exports=JSON.parse('{"slug":"rosatom-plavuchie-aes-indoneziya-eksport","locale":"ru","title":"\xabРосатом\xbb впервые в мире продаст за рубеж электричество с плавучих АЭС","description":"\xabРосатом\xbb подписал первое в мире экспортное соглашение о продаже электричества с плавучих АЭС: 2 блока на 200 МВт для Индонезии. Что это даёт экономике.","blocks":[{"id":"b001","kind":"paragraph","text":"\xabРосатом\xbb и индонезийская компания PT Pembangkit Listrik Nuklir 16 октября 2026 года подписали на Российской энергетической неделе соглашение о снабжении электричеством востока Индонезии. Россия поставит 2 плавучих атомных энергоблока ПЭБ-100 общей мощностью 200 МВт на север острова Хальмахера в провинции Северное Малуку. Гендиректор \xabРосатома\xbb Алексей Лихачев назвал соглашение первой в мире экспортной договорённостью о поставке электричества с плавучего атомного энергоблока. Для Индонезии это ещё и первый атомный проект."},{"id":"b002","kind":"paragraph","text":"Плавучая АЭС — это атомная станция небольшой мощности на барже. Её строят на верфи и буксируют туда, где нет сетей и места для большой станции. Сейчас такая станция в мире одна, \xabАкадемик Ломоносов\xbb на 70 МВт на Чукотке. По оценке аналитика Kept Сергея Роженко, главный плюс технологии в скорости: мощность появляется в 2–3 раза быстрее, чем при строительстве обычной АЭС, которое занимает 8–10 лет."},{"id":"b003","kind":"paragraph","text":"Важна модель сделки. \xabРосатом\xbb продаёт не только оборудование, а электричество на весь срок работы станций: по разрешению Ростехнадзора это 60 лет, и Лихачев рассчитывает, что срок продлят. Проект, по словам индонезийской стороны, идёт на коммерческой основе, за счёт частных инвестиций, без денег бюджета Индонезии. Первое электричество ждут через 5 лет после вступления в силу основных условий контракта. Дальше \xabРосатом\xbb предлагает Индонезии построить большие наземные АЭС и ведёт похожие переговоры в странах Юго-Восточной Азии и Африки."},{"id":"b004","kind":"paragraph","text":"Сколько это стоит, не раскрывают. Ориентир есть только по России: 4 плавучих блока общей мощностью 420 МВт для Баимского горно-обогатительного комбината на Чукотке в 2021 году оценивали в 190,2 млрд рублей с НДС, а тариф называли около 6 рублей за кВт\xb7ч. Первый из них должны ввести в 2028 году. Аналитики считают, что экономику таких станций можно будет оценить только после серии из 8–10 блоков, до этого высокие стартовые затраты делают цену электричества непредсказуемой."},{"id":"b005","kind":"paragraph","text":"Выручка российского экспорта обычно идёт вслед за ценами на нефть и газ. Контракт, где электричество продают десятилетиями, приносит деньги независимо от нефти, и чем больше таких контрактов, тем меньше рубль и бюджет зависят от одного сырья. Кроме того, заказы на плавучие блоки загружают российские верфи и производителей реакторов."},{"id":"b006","kind":"paragraph","text":"Для обычного человека в ближайшие годы эта сделка ничего не изменит: электричество пойдёт не раньше чем через 5 лет, а деньги растянутся на десятилетия. В долгую она про другое: из каких источников Россия будет получать валюту, когда нефть перестанет быть главным. Насколько выгодным окажется проект, станет понятно, только когда назовут цену электричества и затраты, а их пока не раскрыли."},{"id":"b007","kind":"heading","text":"Что \xabРосатом\xbb построит в Индонезии?"},{"id":"b008","kind":"paragraph","text":"2 плавучих атомных энергоблока ПЭБ-100 общей мощностью 200 МВт для севера острова Хальмахера в провинции Северное Малуку. Соглашение подписали 16 октября 2026 года, первое электричество ждут через 5 лет после вступления в силу основных условий контракта."},{"id":"b009","kind":"heading","text":"Что такое плавучая АЭС?"},{"id":"b010","kind":"paragraph","text":"Это атомная станция небольшой мощности на барже, которую строят на верфи и буксируют к месту работы. Единственная работающая сейчас, \xabАкадемик Ломоносов\xbb на 70 МВт, снабжает Чукотку."},{"id":"b011","kind":"heading","text":"Сколько стоит плавучая АЭС?"},{"id":"b012","kind":"paragraph","text":"Стоимость индонезийского проекта не раскрыта. 4 плавучих блока для Чукотки в 2021 году оценивали в 190,2 млрд рублей с НДС, тариф тогда называли около 6 рублей за кВт\xb7ч."}],"sources":[{"label":"Атом тянется к теплу. \xabРосатом\xbb поставит два плавучих энергоблока для Индонезии","url":"https://www.kommersant.ru/doc/9040651"},{"label":"\xabРосатом\xbb подписал соглашение о двух плавучих АЭС для Индонезии","url":"https://www.vedomosti.ru/business/news/2026/10/16/1237826-rosatom-podpisal-soglashenie"},{"label":"Россия согласовала первые в мире международные поставки с плавучих атомных энергоблоков","url":"https://lenta.ru/news/2026/10/16/rossiya-soglasovala-pervye-v-mire-mezhdunarodnye-postavki-s-plavuchih-atomnyh-energoblokov"}],"sourceBodySha256":"364e6fd7aa47727920a3c88d5445a62573e93f518bfc9c74e7e8f7d9926d5290"}')}}]);